var view = DispatchProxy.Create<IDir, DirMembrane>();   // implements IDir

sealed class DirMembrane : DispatchProxy {
    IDir target = null!;
    protected override object? Invoke(MethodInfo m, object?[]? args) {
        if (revoked) throw new InvalidOperationException("revoked");
        for (int i = 0; i < args!.Length; i++)
            if (args[i] is IDir d) args[i] = Wrap(d);        // wrap the way in
        return Wrap(m.Invoke(target, args)!);                // wrap the way out
    }
}
